const UI_PAIRS=Object.entries(UI_TRANSLATIONS).sort((a,b)=>b[0].length-a[0].length);
function t(text){if(typeof state==='undefined'||state.lang!=='en')return String(text);let result=String(text);for(const [zh,en] of UI_PAIRS){if(zh.length===1)result=result.replace(new RegExp('(?<![\\u4e00-\\u9fff])'+zh+'(?![\\u4e00-\\u9fff])','g'),en);else result=result.split(zh).join(en)};return result.replace(/\/\s*days\b/g,'/ day').replace(/\b1 bags\b/g,'1 bag').replace(/\b1 days\b/g,'1 day')}
function localizeHTML(html){if(typeof state==='undefined'||state.lang!=='en')return html;
 // Explicit original values keep rule-based filters and recommendations language-independent.
 html=html.replace(/<option(?![^>]*\bvalue=)([^>]*)>([^<]*)<\/option>/g,(_,attrs,label)=>`<option${attrs} value="${label.replace(/&/g,'&amp;').replace(/"/g,'&quot;')}">${label}</option>`);
 let preserve=0;return (html.match(/<(?:[^"'<>]|"[^"]*"|'[^']*')*>|[^<]+/g)||[]).map(token=>{if(token.startsWith('<')&&token.includes('data-i18n-preserve')){preserve++;return token}if(preserve){if(/^<\/(span|strong|small)/i.test(token))preserve--;return token}return token.startsWith('<')?token.replace(/\b(placeholder|aria-label|alt|title)="([^"]*)"/g,(match,attr,value)=>{if(attr==='value'&&token.startsWith('<option'))return match;return `${attr}="${t(value)}"`}):t(token)}).join('');
}

