/* AMap uses GCJ-02 coordinates; public landmark positions are approximate, not operating branches. */
let regionalConfig={amapKey:'',amapServiceHost:'',authEnabled:false};
let amapPromise=null,placeQueryTimer=null,placeQueryRevision=0,searchMap=null,pickerMap=null;
function placeById(id){return PLACES.find(p=>p.id===id)||state.remotePlaces?.find(p=>p.id===id)||(state.currentGeo?.id===id?state.currentGeo:null)}
function placeLabel(p){return state.lang==='en'?(p.en||p.name):p.name}
function dateLabel(value){if(!value)return '';return value.replace('T',' ')}
function bookingPlaceOptions(value){return (PLACES.some(p=>p.name===value)?[]:[{name:value}]).concat(PLACES).map(p=>`<option value="${esc(p.name)}" ${p.name===value?'selected':''}>${esc(p.en&&state.lang==='en'?p.en:p.name)}</option>`).join('')}
function dateRangeLabel(b){const format=value=>new Intl.DateTimeFormat(state.lang==='en'?'en-GB':'zh-CN',{month:'short',day:'numeric'}).format(new Date(value.slice(0,10)+'T12:00:00'));return format(b.start)+' — '+format(b.end)}
function adjustReturnDate(){const start=q('start'),end=q('end');end.min=start.value;if(end.value<start.value){let next=new Date(start.value+'T12:00:00');next.setDate(next.getDate()+1);end.value=`${next.getFullYear()}-${String(next.getMonth()+1).padStart(2,'0')}-${String(next.getDate()).padStart(2,'0')}`}}
function regionalLocationOptions(query=''){
 const term=query.trim().toLowerCase();
 const matches=PLACES.filter(p=>!term||`${p.name} ${p.en} ${p.detail} ${p.keywords}`.toLowerCase().includes(term));
 const item=p=>`<button type="button" role="option" class="location-option" onclick="chooseLocation('${esc(p.id)}')"><span class="location-symbol">⌖</span><span><strong ${p.en?'':'data-i18n-preserve'}>${esc(placeLabel(p))}</strong><small ${p.en?'':'data-i18n-preserve'}>${esc(p.detail)}</small></span></button>`;
 let html=`<button type="button" class="location-current" onclick="useCurrentLocation()"><span class="location-symbol">◎</span><span><strong>高德定位 · 使用当前位置</strong><small>${regionalConfig.amapKey?'定位后推荐附近地点':'主要地点可直接选择；高德定位待配置'}</small></span></button><button type="button" class="location-current" onclick="openLocationMap()"><span class="location-symbol">▧</span><span><strong>在地图中选择地点</strong><small>成都主要地点 · 不会直接跳转</small></span></button>`;
 if(state.currentGeo)html+='<h4>高德获取的当前位置</h4>'+item(state.currentGeo);
 if(!term){for(const group of ['机场','交通枢纽','热门地点'])html+=`<h4>${group}</h4>`+matches.filter(p=>p.area===group).map(item).join('')}
 else{html+=`<h4>选择具体地点 · ${matches.length} 个结果</h4>`+matches.map(item).join('');const remote=state.remotePlaces||[];if(remote.length)html+='<h4>高德搜索结果</h4>'+remote.map(item).join('');if(!matches.length&&!remote.length)html+='<div class="location-empty">试试“天府机场”“春熙路”或“成都东站”。</div>';if(regionalConfig.amapKey)html+='<small class="muted">高德搜索限定成都市，部分地点保留当地名称。</small>'}
 return html+'<div class="location-empty">地点为取车位置示意，不代表已运营门店。</div>';
}
function regionalChooseLocation(id){const p=placeById(id);if(!p)return;state.selectedLocationId=id;q('pickup').value=placeLabel(p);localStorage.setItem('yichen-recent-location',id);hideLocations();toast(t('已选择：')+placeLabel(p))}
function regionalLocationTyped(value){state.selectedLocationId=null;state.remotePlaces=[];const revision=++placeQueryRevision;clearTimeout(placeQueryTimer);const panel=q('location-panel');if(panel){panel.hidden=false;panel.innerHTML=localizeHTML(regionalLocationOptions(value))}q('pickup')?.setAttribute('aria-expanded','true');if(!regionalConfig.amapKey||!value.trim())return;placeQueryTimer=setTimeout(async()=>{try{const A=await loadAMap();const auto=new A.AutoComplete({city:'成都',citylimit:true});auto.search(value,(status,result)=>{if(revision!==placeQueryRevision||q('pickup')?.value!==value)return;state.remotePlaces=(status==='complete'?result.tips||[]:[]).filter(p=>p.location&&p.id&&/^[A-Za-z0-9_-]+$/.test(p.id)).slice(0,8).map(p=>({id:'amap-'+p.id,name:p.name,detail:`${p.district||''} ${typeof p.address==='string'?p.address:''}`.trim(),lat:p.location.getLat(),lon:p.location.getLng()}));const current=q('location-panel');if(current&&!current.hidden)current.innerHTML=localizeHTML(regionalLocationOptions(value))})}catch(e){/* Built-in Chengdu results remain available if the provider fails. */}},350)}
async function loadAMap(){
 if(!regionalConfig.amapKey)throw new Error(t('高德地图尚未配置，请先选择成都主要地点。'));
 if(window.AMap)return window.AMap;if(amapPromise)return amapPromise;
 amapPromise=new Promise((resolve,reject)=>{window._AMapSecurityConfig={serviceHost:new URL(regionalConfig.amapServiceHost||'/_AMapService',location.origin).href};let script=document.createElement('script');const timeout=setTimeout(()=>{script.remove();amapPromise=null;reject(new Error(t('高德地图加载超时，请检查网络。')))},15000);script.src='https://webapi.amap.com/maps?v=2.0&key='+encodeURIComponent(regionalConfig.amapKey)+'&plugin=AMap.Geolocation,AMap.AutoComplete,AMap.Geocoder';script.onload=()=>{clearTimeout(timeout);if(window.AMap)resolve(window.AMap);else{amapPromise=null;reject(new Error(t('高德地图未能加载，请检查配置。')))}};script.onerror=()=>{clearTimeout(timeout);amapPromise=null;reject(new Error(t('高德地图未能加载，请检查配置。')))};document.head.append(script)});return amapPromise;
}
async function regionalCurrentLocation(){
 try{toast('正在通过高德获取当前位置…');const A=await loadAMap();const geo=new A.Geolocation({enableHighAccuracy:true,timeout:10000,convert:true,needAddress:true});geo.getCurrentPosition((status,result)=>{if(status!=='complete'||!result.position){toast('未能获取位置，请检查浏览器定位权限或手动选择');return}const longitude=result.position.getLng(),latitude=result.position.getLat();state.locatedCoords={longitude,latitude};const nearest=PLACES.map(p=>({...p,km:kmBetween(latitude,longitude,p.lat,p.lon)})).sort((a,b)=>a.km-b.km)[0];if(nearest.km<=40){state.currentGeo={id:'amap-current',name:result.formattedAddress||'当前定位地点',en:`Current location · ${latitude.toFixed(4)}, ${longitude.toFixed(4)}`,detail:result.formattedAddress||`${latitude.toFixed(5)}, ${longitude.toFixed(5)}`,lat:latitude,lon:longitude};state.selectedLocationId=null;q('pickup').value='';showLocations();toast('已获取当前位置，请选择定位地址或附近地点。')}else{showLocations();toast('已定位，但附近没有列出的成都地点，请手动选择。')}})}catch(e){toast(e.message)}
}
function overviewHTML(){return `<div class="chengdu-overview"><div class="map-caption"><span class="eyebrow">CHENGDU</span><h3>成都主要地点</h3><p class="muted">地点概览示意 · 高德地图待配置</p></div><div class="landmark-grid">${PLACES.map(p=>`<div class="landmark"><span>⌖</span><div><b>${esc(placeLabel(p))}</b><small>${esc(p.detail)}</small></div></div>`).join('')}</div></div>`}
function regionalSearchMapHTML(){return `<div id="search-map" class="regional-map">${regionalConfig.amapKey?'<div class="map-loading">正在加载高德地图…</div>':overviewHTML()}</div><p class="muted map-note">标注为成都主要地点，不代表实际营业门店。地图不提供实时车辆库存。</p>`}
async function mountSearchMap(){if(!regionalConfig.amapKey)return;try{const A=await loadAMap();if(!q('search-map'))return;searchMap=new A.Map('search-map',{zoom:11,center:[104.0665,30.5723],lang:state.lang==='en'?'en':'zh_cn'});const markers=PLACES.map(p=>{const marker=new A.Marker({position:[p.lon,p.lat],title:placeLabel(p)});marker.on('click',()=>{new A.InfoWindow({content:localizeHTML(`<div class="map-info"><b>${esc(placeLabel(p))}</b><p>${esc(p.detail)}</p><small>地点示意</small></div>`)}).open(searchMap,[p.lon,p.lat])});return marker});searchMap.add(markers);searchMap.setFitView(markers)}catch(e){const el=q('search-map');if(el)el.innerHTML=localizeHTML(overviewHTML());toast(e.message)}}
function disposeMaps(){if(searchMap){searchMap.destroy();searchMap=null}}
