const DESTINATION_CATEGORIES=[{"id": "heritage", "name": "古街人文", "nameEn": "Heritage lanes"}, {"id": "landmarks", "name": "城市地标", "nameEn": "City landmarks"}, {"id": "arts", "name": "艺术街区", "nameEn": "Art districts"}, {"id": "gardens", "name": "湖畔花园", "nameEn": "Lakeside gardens"}, {"id": "pandas", "name": "熊猫亲子", "nameEn": "Pandas and family"}, {"id": "landscapes", "name": "山水自驾", "nameEn": "Scenic drives"}];
function destinationInCategory(d,id){return id==='all'||(d.categories||[]).includes(id)||(['city','nature'].includes(id)&&d.group===id)}
function destinationCategoryLabel(d){const category=DESTINATION_CATEGORIES.find(c=>(d.categories||[]).includes(c.id));return category?tourText(category,'name'):tourGroup(d.group)}
function tourCopy(zh,en){return state.lang==='en'?en:zh}
function tourText(item,key){return state.lang==='en'?(item[key+'En']||item[key]):item[key]}
function tourGroup(group){return {city:tourCopy('城市漫游','City walks'),nature:tourCopy('四川山水','Sichuan landscapes'),weekend:tourCopy('周末慢游','Weekend escape'),west:tourCopy('川西长线','Western Sichuan')}[group]||group}
function tourImageCredit(){return tourCopy('实景照片','Location photo')}
function destinationPhotos(d){return window.DestinationGallery?.photos(d)||[{src:d.image,label:tourText(d,'name')}]}
function destinationImagesHTML(d,eager=false){return destinationPhotos(d).map((p,i)=>`<img loading="${eager&&!i?'eager':'lazy'}" ${i?'data-src':'src'}="${esc(webImage(p.src))}" alt="${esc(tourText(d,'name')+' · '+(state.lang==='en'?(p.labelEn||'Photo'):p.label))}" ${i?'hidden':''} style="object-position:50% 50%"/>`).join('')}
function destinationCardControls(d){return destinationPhotos(d).length>1?`<div class="destination-card-controls"><button data-prev aria-label="${tourCopy('上一张','Previous photo')}">‹</button><span data-count>1 / ${destinationPhotos(d).length}</span><button data-next aria-label="${tourCopy('下一张','Next photo')}">›</button></div>`:''}
function tourDestinationCard(d){return `<a class="destination-card" data-destination-gallery data-destination="${d.id}" href="#/destination/${d.id}"><div class="destination-card-media">${destinationImagesHTML(d)}</div><div class="destination-card-copy">${destinationCardControls(d)}<small class="destination-kind">${destinationCategoryLabel(d)}</small><h3>${tourText(d,'name')}</h3><p>${tourText(d,'sub')} ↗</p></div></a>`}
function tourDestinationsPage(){const group=state.destinationGroup||'all',items=DEST.filter(d=>destinationInCategory(d,group));return `<main class="page wrap"><div class="subhero"><span class="eyebrow">DESTINATIONS · CHENGDU & SICHUAN</span><h1>${tourCopy('把成都，慢慢看。','See Chengdu, slowly.')}</h1><p>${tourCopy('从巷子与城市夜色，到雪山与清澈海子。','From courtyard lanes and city lights to snow peaks and clear lakes.')}</p></div><div class="tour-filters">${[{id:'all',name:'全部目的地',nameEn:'All destinations'},...DESTINATION_CATEGORIES].map(category=>`<button class="chip ${group===category.id?'active':''}" aria-pressed="${group===category.id}" onclick="state.destinationGroup='${category.id}';render()">${tourText(category,'name')}<span class="category-count">${DEST.filter(d=>destinationInCategory(d,category.id)).length}</span></button>`).join('')}</div><div class="dest-grid tour-dest-grid">${items.map(tourDestinationCard).join('')}</div><a class="photo-credit-link" href="./photo-credits.html" target="_blank" rel="noopener noreferrer">${tourCopy('摄影来源与许可','Photography credits')}</a></main>`}
function tourDestinationPage(id){const d=DEST.find(d=>d.id===id);if(!d)return notFoundPage();const routes=TOUR_ROUTES.filter(r=>r.destination===d.id);return `<main class="page wrap"><div class="destination-detail-hero" data-destination-gallery>${destinationImagesHTML(d,true)}${destinationPhotos(d).length>1?`<div class="destination-gallery-controls"><button data-prev aria-label="${tourCopy('上一张','Previous photo')}">←</button><span data-count>1 / ${destinationPhotos(d).length}</span><button data-next aria-label="${tourCopy('下一张','Next photo')}">→</button><button data-pause aria-pressed="false">${tourCopy('暂停轮播','Pause slideshow')}</button></div>`:''}<div class="destination-detail-caption"><span class="eyebrow">${destinationCategoryLabel(d)}</span><h1>${tourText(d,'name')}</h1><p>${tourText(d,'sub')}</p></div></div>${destinationPhotos(d).some(p=>p.source)?`<div class="gallery-source-links">${destinationPhotos(d).map((p,i)=>p.source?`<a data-source-index="${i}" ${i?'hidden':''} href="${esc(p.source)}" target="_blank" rel="noopener noreferrer">${tourCopy('照片来源','Photo source')} · ${esc((state.lang==='en'?(p.labelEn||'Photo'):p.label))} ↗</a>`:'').join('')}</div>`:''}<div class="destination-detail-grid"><section class="tour-info"><span class="eyebrow">A LITTLE TIME, A GOOD JOURNEY</span><h2>${tourCopy('留一点时间，给这里。','Leave a little time for this place.')}</h2><dl><div><dt>${tourCopy('建议节奏','Suggested pace')}</dt><dd>${tourText(d,'days')}</dd></div><div><dt>${tourCopy('路线','Route')}</dt><dd>${tourText(d,'terrain')}</dd></div><div><dt>${tourCopy('停车与步行','Parking and walking')}</dt><dd>${tourText(d,'tip')}</dd></div><div><dt>${tourCopy('沿途补能','Fuel or charging')}</dt><dd>${tourText(d,'fuel')}</dd></div></dl><a class="link" href="${d.sourceUrl}" target="_blank" rel="noopener noreferrer">${tourCopy('查看景点资料','View destination information')} ↗</a></section><aside class="tour-side"><h3>${tourCopy('为这次出发选一辆车','Choose a vehicle for the journey')}</h3><p>${tourCopy('先选地点与日期，再核对具体车型、座位数与实车配置。','Choose dates and pickup, then confirm the exact vehicle and equipment.')}</p><a class="btn" href="#/search">${tourCopy('查看座驾','Explore vehicles')} ↗</a><a class="link" href="#/inspiration">${tourCopy('探索更多路线','More route inspiration')} ↗</a></aside></div>${routes.length?`<section class="tour-related"><div class="section-head"><div><span class="eyebrow">ROUTE IDEAS</span><h2>${tourCopy('顺路，把美景串起来。','Link the places along the way.')}</h2></div></div><div class="tour-route-grid">${routes.slice(0,3).map(tourRouteCard).join('')}</div></section>`:''}</main>`}
function tourRouteCard(r){const d=DEST.find(d=>d.id===r.destination);return `<a class="tour-route-card" href="#/route/${r.id}"><div class="tour-route-image"><img loading="lazy" src="${esc(webImage(destinationPhotos(d)[0].src))}" alt="${esc(tourText(r,'name'))}" style="object-position:50% 50%"/><span class="tour-duration">${tourText(r,'days')}</span></div><div class="tour-route-copy"><span class="eyebrow">${tourGroup(r.group)}</span><h3>${tourText(r,'name')}</h3><p>${tourText(r,'sub')}</p><div class="tour-stops">${(state.lang==='en'?r.stopsEn:r.stops).join(' → ')}</div><span class="tour-route-link">${tourCopy('查看路线','View route')} ↗</span></div></a>`}
function tourInspirationPage(){const group=state.routeGroup||'all',items=TOUR_ROUTES.filter(r=>group==='all'||r.group===group);return `<main class="page wrap"><div class="subhero"><span class="eyebrow">ROUTE INSPIRATION</span><h1>${tourCopy('从想去的地方出发。','Begin with the place you want to go.')}</h1><p>${tourCopy('十二种节奏，探索成都与四川。','Twelve ways to explore Chengdu and Sichuan.')}</p></div><div class="tour-filters">${[['all','全部路线','All routes'],['city','城市漫游','City walks'],['weekend','周末慢游','Weekend escapes'],['west','川西长线','Western Sichuan']].map(([id,zh,en])=>`<button class="chip ${group===id?'active':''}" onclick="state.routeGroup='${id}';render()">${tourCopy(zh,en)}</button>`).join('')}</div><div class="tour-route-grid">${items.map(tourRouteCard).join('')}</div><p class="tour-route-footnote">${tourCopy('路线与天数为灵感参考，可按天气、道路、景区安排与同行者需要调整。','Routes and durations are suggestions. Adapt them to weather, roads, visitor arrangements and your group.')}</p></main>`}
function tourRoutePage(id){const r=TOUR_ROUTES.find(r=>r.id===id);if(!r)return notFoundPage();const d=DEST.find(d=>d.id===r.destination),stops=state.lang==='en'?r.stopsEn:r.stops;return `<main class="page wrap"><div class="destination-detail-hero"><img src="${esc(webImage(destinationPhotos(d)[0].src))}" alt="${esc(tourText(r,'name'))}" style="object-position:50% 50%"/><div class="destination-detail-caption"><span class="eyebrow">${tourGroup(r.group)} · ${tourText(r,'days')}</span><h1>${tourText(r,'name')}</h1><p>${tourText(r,'sub')}</p></div></div>${destinationPhotos(d).some(p=>p.source)?`<div class="gallery-source-links">${destinationPhotos(d).map((p,i)=>p.source?`<a data-source-index="${i}" ${i?'hidden':''} href="${esc(p.source)}" target="_blank" rel="noopener noreferrer">${tourCopy('照片来源','Photo source')} · ${esc((state.lang==='en'?(p.labelEn||'Photo'):p.label))} ↗</a>`:'').join('')}</div>`:''}<div class="destination-detail-grid"><section class="tour-info"><span class="eyebrow">YOUR WAY THROUGH</span><h2>${tourCopy('一站一站，慢慢抵达。','One stop at a time.')}</h2><ol class="tour-route-timeline">${stops.map((s,i)=>`<li><span>${String(i+1).padStart(2,'0')}</span><div><h3>${esc(s)}</h3><small>${tourCopy('路线参考节点','Suggested route stop')}</small></div></li>`).join('')}</ol><p class="tour-route-note">${tourText(r,'note')}</p><a class="link" href="#/destination/${d.id}">${tourCopy('查看目的地详情','View destination details')} ↗</a></section><aside class="tour-side"><h3>${tourCopy('选好路线，再选座驾。','Choose the route, then the vehicle.')}</h3><p>${tourCopy('实际座位、行李空间和车辆配置需在预订前确认。','Confirm actual seating, luggage space and equipment before booking.')}</p><a class="btn" href="#/search?filter=${encodeURIComponent(r.filter)}&brand=all">${tourCopy('为路线查看座驾','Explore vehicles for this route')} ↗</a><a class="link" href="#/inspiration">${tourCopy('返回路线灵感','Back to route inspiration')}</a></aside></div></main>`}

