    function journeyCard(j){const en=state.lang==='en',c=CARS.find(c=>c.id===j.car),query=new URLSearchParams({filter:j.filter,brand:j.brand||'all'});return `<a href="#/search?${query}" class="journey-card"><div class="journey-media">${vehiclePhoto(c,'loading="lazy" alt="'+esc(en?c.en:c.name)+'"')}${vehiclePhotoNotice(c)}<span class="journey-icon" aria-hidden="true">↗</span></div><div class="journey-card-body"><span class="eyebrow">${en?c.en:c.type}</span><h3>${en?j.en:j.name}</h3><p>${en?j.subEn:j.sub}</p></div></a>`}
    const DEST=TOUR_DESTINATIONS;
    const HOME_DESTINATION_IDS=['kuanzhai','chunxi','twins','luhu-cpi','dujiangyan','qingcheng','siguniang','jiuzhai'];
    const money=n=>n==null?t('待报价'):'¥'+Math.round(n).toLocaleString('zh-CN');
    function storedJSON(storage,key,fallback){try{return JSON.parse(storage.getItem(key))??fallback}catch{return fallback}}
    const state={route:location.hash.slice(1)||'/',sort:'推荐',filter:'全部',brand:'all',map:false,mobileFilter:false,criteria:[],maxPrice:1500,lang:localStorage.getItem('yichen-lang')||'zh',favorites:storedJSON(localStorage,'yichen-favs',[]),booking:storedJSON(sessionStorage,'yichen-booking',null),step:1,protection:'基础保障',extras:[],match:null,matchRequest:storedJSON(sessionStorage,'yichen-match-request',null),toast:null};
    const app=document.getElementById('app');
    function save(){localStorage.setItem(state.account?'yichen-favs-'+state.account.id:'yichen-favs',JSON.stringify(state.favorites));sessionStorage.setItem('yichen-booking',JSON.stringify(state.booking))}
    function nav(to){location.hash=to;state.route=to;render();window.scrollTo(0,0)}
    function toast(s){state.toast=s;let el=document.querySelector('.toast');if(el)el.remove();el=document.createElement('div');el.className='toast';el.textContent=t(s);document.body.append(el);setTimeout(()=>el.remove(),3000)}
    function q(id){return document.getElementById(id)}
    function dateAfter(n){let d=new Date();d.setDate(d.getDate()+n);d.setHours(10,0,0,0);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
    function book(){return state.booking||{car:'x5',pickup:'成都天府国际机场',pickupId:'tianfu',start:dateAfter(8),end:dateAfter(11),same:true}}
    function days(){const b=book(),instant=value=>Date.parse(value.length===10?value+'T00:00:00+08:00':value.length===16?value+':00+08:00':value),duration=(instant(b.end)-instant(b.start))/86400000;return Number.isFinite(duration)?Math.max(1,Math.ceil(duration)):1}
    function totals(car,withOptions=false){const d=days();if(car.price==null)return {d,base:null,service:null,tax:null,protection:null,extras:null,total:null};const base=car.price*d,service=120,tax=Math.round((base+service)*.09),protection=withOptions?(state.protection==='标准保障'?80*d:state.protection==='尊享保障'?150*d:0):0,extras=withOptions?state.extras.length*60*d:0;return {d,base,service,tax,protection,extras,total:base+service+tax+protection+extras}}
    function header(){let en=state.lang==='en';return `<header><div class="wrap nav"><a href="#/" class="brand brand-lockup"><span class="brand-mark" aria-hidden="true"><img src="./images/brand/yichen-mark.webp?v=perf-v56" width="48" height="48" alt=""/></span><span class="brand-wordmark"><strong>YICHEN</strong><span>DRIVE</span></span></a><nav class="navlinks" aria-label="主导航"><a href="#/">${en?'Home':'首页'}</a><a href="#/search">${en?'Cars':'租车'}</a><a href="#/destinations">${en?'Destinations':'目的地'}</a><a href="#/inspiration">${en?'Routes':'路线灵感'}</a><a href="#/services">${en?'Service areas':'服务地区'}</a><a href="#/about">${en?'About':'关于我们'}</a></nav><div class="navright"><button class="nav-search" onclick="nav('/search')" aria-label="搜索"><svg viewBox="0 0 24 24" width="24" height="24" aria-hidden="true"><circle cx="10.5" cy="10.5" r="6.5"/><path d="m15.5 15.5 5 5"/></svg></button><button class="textnav" onclick="nav('/garage')">${en?'Garage':'我的车库'}</button><button class="textnav" onclick="toggleLang()">${en?'中文':'EN'}</button><button class="login" onclick="showAccount()">${state.account?`<span data-i18n-preserve>${esc(state.account.name)}</span>`:(en?'Sign in':'登录 / 注册')}</button><button class="mobile-menu" onclick="toggleMenu()" aria-label="打开菜单" aria-expanded="false" aria-controls="mobile-panel">☰</button></div></div><div id="mobile-panel" class="mobile-panel"><a href="#/">首页</a><a href="#/search">租车</a><a href="#/destinations">目的地</a><a href="#/inspiration">路线灵感</a><a href="#/garage">我的车库</a><a href="#/trips">我的旅程</a><a href="#" onclick="showAccount();return false">登录 / 注册</a><a href="#/match">YICHEN Match</a><a href="#/services">服务地区</a><a href="#/about">关于我们</a><a href="#" onclick="toggleLang();return false">中文 / EN</a></div></header>`}
    function footer(){return serviceFooter()}
    function card(c){return catalogCard(c,'fleet')}
    function searchForm(){let b=book();return `<div class="search-wrap wrap"><form class="search-box" onsubmit="doSearch(event)"><div class="field location-field"><label for="pickup">取车地点</label><input id="pickup" role="combobox" aria-autocomplete="list" aria-controls="location-panel" aria-expanded="false" required autocomplete="off" value="${esc(placeById(b.pickupId)?placeLabel(placeById(b.pickupId)):b.pickup)}" placeholder="输入城市、机场或具体地点" onfocus="showLocations()" oninput="locationTyped(this.value)" onkeydown="locationKeydown(event)"/><div id="location-panel" class="location-panel" role="listbox" hidden></div></div><div class="field"><label for="start">取车日期</label><input id="start" type="date" required min="${dateAfter(0)}" value="${b.start.slice(0,10)}" onchange="adjustReturnDate()"/></div><div class="field"><label for="end">还车日期</label><input id="end" type="date" required min="${b.start.slice(0,10)}" value="${b.end.slice(0,10)}"/></div><button class="btn search-cta" type="submit">搜索车辆 <span>↗</span></button></form><div class="search-bottom"><label class="check"><input id="same" type="checkbox" ${b.same?'checked':''}/> 同一地点还车</label><span>先选地点与日期，确认行程时选择具体时刻</span></div></div>`}
    function home(){return `<main class="page"><section class="hero"><img class="hero-image" width="1536" height="1024" srcset="./images/optimized/hero-mobile-v56.webp 768w, ./images/optimized/hero-v2-cbe4ebc8.webp 1536w" sizes="100vw" fetchpriority="high" decoding="async" src="${PHOTO.hero}" alt="GT 跑车行驶在公路上" onerror="this.onerror=null;this.src='${PHOTO.porsche}'"/><div class="wrap hero-inner"><div class="hero-copy"><span class="eyebrow">YICHEN DRIVE · CURATED JOURNEYS</span><h1>去更远的地方，<br/>遇见更好的自己。</h1><p>精选高品质自驾车型，让每一次出发，都成为难忘的旅程。</p><div class="hero-actions"><button class="btn" onclick="document.querySelector('#pickup').focus()">开始旅程 ↗</button><button class="btn ghost" onclick="nav('/destinations')">探索路线</button></div></div><div class="hero-side">DRIVE EASY.<br/>ROAM FREE.</div></div></section>${searchForm()}${rentalProcessHTML('home')}<section class="section wrap" style="padding-top:0"><div class="section-head"><div><span class="eyebrow">CURATED FLEET</span><h2>精选车型</h2><p>${serviceCopy('六种车型类别，每类先呈现一辆。','Six vehicle categories, one selection for each.')}</p></div><a class="btn ghost" href="#/search">查看全部车型 ↗</a></div><div class="fleet-grid home-fleet-grid">${FEATURED_CARS.map(card).join('')}</div></section><section class="section wrap home-destinations" id="popular-destinations"><div class="section-head"><div><span class="eyebrow">EXPLORE DESTINATIONS</span><h2>热门目的地</h2><p>探索经典自驾路线，发现不可错过的风景。</p></div><a class="btn ghost" href="#/destinations">${serviceCopy('查看全部目的地','All destinations')} ↗</a></div><div class="dest-grid home-dest-grid">${HOME_DESTINATION_IDS.map(id=>DEST.find(d=>d.id===id)).filter(Boolean).map(tourDestinationCard).join('')}</div></section><section class="section wrap"><div class="section-head"><div><span class="eyebrow">FIND BY JOURNEY</span><h2>选择你的旅行方式</h2><p>不同旅程，不同驾驭体验。</p></div></div><div class="journey-grid">${JOURNEYS.map(journeyCard).join('')}</div></section><section class="wrap"><div class="match-band"><div><span class="eyebrow" style="color:#bdbeb4">YICHEN MATCH</span><h2>不知道开什么车？</h2><p>告诉 YICHEN 你的旅程，我们帮你找到更合适的座驾。</p></div><button class="btn light" onclick="nav('/match')">开始匹配 ↗</button></div></section><section class="wrap benefits">${[['◇','精选高品质车辆','定期维护，放心出行'],['◈','价格透明','费用明细提前可见'],['↺','变更先沟通','取消与变更按确认合同办理'],['✳','人工跟进','提交需求后核对车辆与行程']].map(x=>`<div class="benefit"><i>${x[0]}</i><b>${x[1]}</b><p>${x[2]}</p></div>`).join('')}</section></main>`}
    function search(){let params=new URLSearchParams((state.route.split('?')[1]||''));if(params.has('filter'))state.filter=params.get('filter');restoreSearchOptions(params);if(params.has('brand'))state.brand=BRANDS.some(b=>b.id===params.get('brand'))?params.get('brand'):'all';let arr=CARS.filter(c=>(state.brand==='all'||c.brand===state.brand)&&(state.filter==='全部'||state.filter==='推荐'||(state.filter==='SUV'?c.type.includes('SUV'):state.filter==='新能源'?['my','denza-d9'].includes(c.id):state.filter==='敞篷'?c.type.includes('敞篷'):state.filter==='豪华'?c.type.includes('豪华'):state.filter==='轿车'?c.type.includes('轿车'):state.filter==='MPV'?c.type.includes('MPV'):state.filter==='中巴'?c.type.includes('中巴'):state.filter==='商务'?c.scene==='商务出行':true))&&(c.price==null?state.maxPrice===1500:c.price<=state.maxPrice)&&state.criteria.every(x=>meetsCriterion(c,x)));if(state.sort==='价格最低')arr.sort((a,b)=>a.price==null?1:b.price==null?-1:a.price-b.price);if(state.sort==='价格最高')arr.sort((a,b)=>a.price==null?1:b.price==null?-1:b.price-a.price);return `<main class="page"><div class="subhero"><div class="wrap"><span class="eyebrow">FIND YOUR DRIVE</span><h1>为这趟旅程，找到更合适的车。</h1><p>${esc(book().pickup)} · ${dateRangeLabel(book())} · ${days()} 天</p><button class="btn ghost" style="margin-top:18px" onclick="editTrip()">修改地点与时间 ↗</button></div></div><div class="wrap search-layout"><section class="filters filter-panel" id="filters" aria-label="筛选条件"><div class="filter-heading"><h3>筛选条件</h3><button class="filter-reset" onclick="clearSearchFilters()">${state.lang==='en'?'Clear':'清除'}</button></div><fieldset class="filter-group brand-filter"><legend>${state.lang==='en'?'Car brand':'汽车品牌'}</legend><div class="filter-options">${BRANDS.map(b=>`<label class="filter-option brand-option ${state.brand===b.id?'is-selected':''}"><input type="radio" name="brand" value="${b.id}" ${state.brand===b.id?'checked':''} onchange="setBrand('${b.id}')"/><span>${brandLabel(b.id)}</span></label>`).join('')}</div></fieldset><fieldset class="filter-group type-filter"><legend>车型</legend><div class="filter-options">${['全部','轿车','SUV','MPV','中巴','新能源','敞篷','豪华'].map(f=>`<label class="filter-option ${state.filter===f?'is-selected':''}"><input type="radio" name="type" value="${f}" ${state.filter===f?'checked':''} onchange="setFilter('${f}')"/><span>${f}</span></label>`).join('')}</div></fieldset><div class="filter-bottom"><fieldset class="filter-group preference-filter"><legend>出行偏好</legend><div class="filter-options">${['5 座及以上','7 座及以上','3 件行李及以上','AWD / 四驱','自动挡','Apple CarPlay'].map(x=>`<label class="filter-option preference-option ${state.criteria.includes(x)?'is-selected':''}"><input type="checkbox" value="${x}" ${state.criteria.includes(x)?'checked':''} onchange="criteriaChange('${x}',this.checked)"/><span><i aria-hidden="true"></i>${x}</span></label>`).join('')}</div><p class="configuration-note">${serviceCopy('座位与行李按车型类别提供候选；四驱与自动挡展示包含对应版本的车系，具体实车版本和装载方案在预订前确认。','Seat and luggage filters include relevant body-type candidates. Drive and transmission filters include model families with matching variants; confirm the actual trim and loading plan before booking.')}</p></fieldset><fieldset class="filter-group price-filter"><legend>价格区间</legend><div class="price-filter-caption"><label for="price-range">日租价</label><span id="price-label">${money(state.maxPrice)}</span></div><input id="price-range" aria-label="日租价" type="range" min="200" max="1500" value="${state.maxPrice}" oninput="q('price-label').textContent=money(this.value)" onchange="state.maxPrice=+this.value;syncSearchFilters();render()"/><div class="price-filter-limits"><span>${money(200)}</span><span>${money(1500)}</span></div></fieldset></div></section><div><div class="results-toolbar"><span class="muted">找到 ${arr.length} 款座驾</span><div><button class="chip ${state.map?'':'active'}" onclick="state.map=false;render()">列表</button><button class="chip ${state.map?'active':''}" onclick="state.map=true;render()">地图</button></div></div><div class="chips">${['推荐','价格最低','价格最高'].map(x=>`<button class="chip ${(x===state.sort)?'active':''}" onclick="chip('${x}')">${x}</button>`).join('')}</div>${state.map?regionalSearchMapHTML():arr.length?`<div class="catalog-grid">${arr.map(c=>catalogCard(c,'result')).join('')}</div>`:`<div class="empty"><h3>暂时没有符合条件的车辆</h3><p>可调整日期、扩大取车范围，或取消部分车型筛选。</p><button class="btn" onclick="clearSearchFilters()">查看全部车型</button></div>`}</div></div></main>`}
    function breakdown(c){if(c.price==null)return '<p class="configuration-note">版本与日租价格确认后显示费用明细。</p>';let t=totals(c,true);return `<div class="breakdown"><div><span>基础租金 · ${t.d} 天</span><span>${money(t.base)}</span></div><div><span>门店服务费</span><span>${money(t.service)}</span></div><div><span>税费（预估）</span><span>${money(t.tax)}</span></div><div><span>保障服务</span><span>按报价确认</span></div>${t.protection?`<div><span>${state.protection}</span><span>${money(t.protection)}</span></div>`:''}${t.extras?`<div><span>附加服务</span><span>${money(t.extras)}</span></div>`:''}<div><span>优惠</span><span>—</span></div><div class="total"><span>预计总计</span><span>${money(t.total)}</span></div></div>`}
    function carPage(id){let c=CARS.find(x=>x.id===id)||CARS[0];return `<main class="page wrap"><div class="detail-top"><span class="eyebrow">${c.en}</span><h1>${c.name}</h1><div class="muted">${c.type} · 配置待核实 · 图片仅示意</div></div>${vehicleShowroom(c)}<div class="detail-grid"><div><div class="detail-block"><span class="eyebrow">WHY IT FITS</span><h2>为什么适合你</h2><p>${c.reason}</p></div><div class="detail-block"><h2>车辆配置</h2>${configurationHTML(c)}</div><div class="detail-block"><h2>租赁包含</h2>${servicePointsHTML(RENTAL_SERVICE_ITEMS)}<p class="configuration-note">上述为交付服务说明；保险、救援费用与服务时段按确认合同执行。</p></div>${insuranceGuideHTML()}<div class="detail-block"><h2>可选服务</h2>${servicePointsHTML(OPTIONAL_SERVICE_ITEMS)}</div><div class="detail-block"><h2>旅程评价</h2>${reviewsHTML(c)}</div></div><aside class="price-panel"><span class="eyebrow">TRANSPARENT PRICING</span><h3>${c.price==null?'待报价':money(c.price)+' / 天'}</h3><span class="muted">${c.price==null?'版本与报价待确认':'演示价'}</span><p class="muted" style="font-size:.8rem">${esc(book().pickup)} · ${days()} 天</p>${breakdown(c)}<button class="btn" onclick="startBooking('${c.id}')">提交用车需求 ↗</button><a class="btn outline" style="margin-top:14px" href="#/enquiry?car=${c.id}">咨询这辆车 ↗</a><p class="muted" style="font-size:.73rem;margin:13px 0 0">演示报价；保障费用和最终总价需人工确认，无真实库存或支付。</p></aside></div></main>`}
    function bookingPage(){let b=book(),c=CARS.find(x=>x.id===b.car)||CARS[1];let step=state.step;let contents={1:`<h2>确认你的行程</h2><p class="muted">现在选择具体取还车时刻，最终租期按每 24 小时计 1 天，不足 24 小时计 1 天。所有时刻均为北京时间（UTC+8）。</p><div class="form-grid"><div class="formfield"><label for="b-pickup">取车地点</label><select id="b-pickup">${bookingPlaceOptions(b.pickup)}</select></div><div class="formfield"><label for="b-return">还车地点</label><select id="b-return">${bookingPlaceOptions(b.returnAt||b.pickup)}</select></div><div class="formfield"><label for="b-start">取车日期</label><input id="b-start" type="date" min="${dateAfter(0)}" value="${b.start.slice(0,10)}"/></div><div class="formfield"><label for="b-end">还车日期</label><input id="b-end" type="date" min="${b.start.slice(0,10)}" value="${b.end.slice(0,10)}"/></div><div class="formfield"><label for="b-start-time">取车时刻</label><input id="b-start-time" type="time" required value="${b.start.slice(11,16)||'10:00'}"/></div><div class="formfield"><label for="b-end-time">还车时刻</label><input id="b-end-time" type="time" required value="${b.end.slice(11,16)||'10:00'}"/></div></div>`,2:`<h2>保障与服务</h2><p class="muted">根据需要选择，基础保障已包含。</p>${[['基础保障',0],['标准保障',80],['尊享保障',150]].map(x=>`<label class="option"><input type="radio" name="protection" ${state.protection===x[0]?'checked':''} onchange="state.protection='${x[0]}';render()"/><b>${x[0]}</b><small>${x[1]?`+${money(x[1])}/天`:'已包含'}</small></label>`).join('')}<h3 style="margin-top:25px">附加服务</h3>${['额外驾驶员','儿童座椅','额外里程','提前加油','雪地装备'].map(x=>`<label class="option"><input type="checkbox" ${state.extras.includes(x)?'checked':''} onchange="extra('${x}',this.checked)"/>${x}<small>+¥60/天 · 演示价</small></label>`).join('')}`,3:`<h2>驾驶员信息</h2><p class="muted">请填写与取车时证件一致的信息。</p><div class="form-grid"><div class="formfield"><label for="driver-name">姓名</label><input id="driver-name" placeholder="请输入姓名" value="${esc(b.name||'')}"/></div><div class="formfield"><label for="driver-phone">联系电话</label><input id="driver-phone" type="tel" placeholder="请输入手机号" value="${esc(b.phone||'')}"/></div><div class="formfield"><label for="driver-email">电子邮箱</label><input id="driver-email" type="email" placeholder="用于接收行程信息" value="${esc(b.email||'')}"/></div><div class="formfield"><label for="driver-license">驾驶证号码</label><input id="driver-license" placeholder="演示可留空" value="${esc(b.license||'')}"/></div></div>`,4:`<h2>模拟支付</h2><p class="muted">请核对费用。点击下方按钮将创建演示订单，不会扣款。</p><div class="option"><b>演示支付</b><small>无需银行卡</small></div>${breakdown(c)}`};return `<main class="page wrap booking-grid"><div><span class="eyebrow">RESERVATION</span><h1>准备出发。</h1><div class="flow">${['行程确认','保障与服务','驾驶员','支付','完成'].map((x,i)=>`<span class="${step===i+1?'on':''}">${i+1} ${x}</span>${i<4?'<i></i>':''}`).join('')}</div><div class="booking-content">${contents[step]||contents[1]}<div class="booking-actions"><button class="btn ghost" onclick="bookingBack()">${step===1?'返回车型':'上一步'}</button><button class="btn" onclick="bookingNext()">${step===4?'确认模拟支付':'继续'} ↗</button></div></div></div><aside class="price-panel">${vehiclePhoto(c,'loading="lazy" alt="'+esc(c.name)+' 车型参考图片"')}<h3>${c.name}</h3><p class="muted" style="font-size:.8rem">${esc(b.pickup)}<br/>${b.start.replace('T',' ')} — ${b.end.replace('T',' ')}</p>${breakdown(c)}<p class="muted" style="font-size:.72rem">所有金额为演示估算，真实价格以正式服务上线后为准。</p></aside></main>`}
    function success(){let b=book(),c=CARS.find(x=>x.id===b.car)||CARS[1];return `<main class="page success"><div class="mark">✓</div><span class="eyebrow">JOURNEY READY</span><h1>你的旅程已经准备好了。</h1><p class="muted">${state.account?'演示预订已保存到你的账户，可在“我的旅程”查看。':'演示预订已保存到此设备，可在“我的旅程”查看。'}</p><div class="success-card"><div><span>车型</span><b>${c.name}</b></div><div><span>取车地点</span><b>${esc(b.pickup)}</b></div><div><span>取车时间</span><b>${b.start.replace('T',' ')}</b></div><div><span>还车时间</span><b>${b.end.replace('T',' ')}</b></div><div><span>演示订单号</span><b>${b.order||'YC-DEMO-20261004'}</b></div></div><div style="display:flex;gap:10px;justify-content:center;flex-wrap:wrap"><button class="btn" onclick="nav('/trips')">查看我的旅程</button><button class="btn ghost" onclick="calendar()">添加至日历</button><button class="btn ghost" onclick="shareTrip()">分享行程</button></div><p class="muted" style="margin-top:35px;font-size:.84rem">出发前请准备驾驶证与支付银行卡，提前到店，并在取车时拍照验车。</p></main>`}
    function trips(){return regionalTrips()}
    function garage(){let fav=CARS.filter(c=>state.favorites.includes(c.id));return `<main class="page wrap" style="min-height:65vh"><div class="subhero"><span class="eyebrow">MY GARAGE</span><h1>我的车库</h1><p>收藏心仪座驾，最多比较三款。</p></div>${fav.length?`<div class="garage-grid">${fav.map(c=>`<div class="mini-card">${vehiclePhoto(c,'loading="lazy" alt="'+esc(c.name)+' 车型参考图片"')}<div><h3>${c.name}</h3><p class="muted">${money(c.price)} / 天 · 配置待核实</p><button class="btn ghost" onclick="nav('/car/${c.id}')">查看车辆</button> <button class="link" onclick="favorite('${c.id}')">取消收藏</button></div></div>`).join('')}</div>${fav.length>1?`<h2 style="font-size:2rem">车型对比</h2><div class="compare"><table><tr><th>维度</th>${fav.slice(0,3).map(c=>`<th>${c.name}</th>`).join('')}</tr>${[['日租价',c=>money(c.price)],['座位',c=>capacityLabel(c,'seats','座')],['行李',c=>capacityLabel(c,'bags','件')],['能源',c=>configValue(c,'energy')],['驱动',c=>configValue(c,'drive')],['适用场景',c=>c.scene]].map(r=>`<tr><td>${r[0]}</td>${fav.slice(0,3).map(c=>`<td>${r[1](c)}</td>`).join('')}</tr>`).join('')}</table></div>`:''}`:`<div class="empty" style="margin:35px 0"><h3>车库里还没有座驾</h3><p>在车型卡片点亮爱心，随时回来比较。</p><button class="btn" onclick="nav('/search')">探索车型</button></div>`}</main>`}
    function destinations(){return tourDestinationsPage()}
    function destination(id){return tourDestinationPage(id)}
    function matchCopy(zh,en){return state.lang==='en'?en:zh}
    function matchRequest(){return state.matchRequest||{start:'',destination:'',people:2,bags:1,type:'周末出逃',budget:700,priority:'舒适'}}
    function matchVehicleStory(car){
      const stories={
        jetta:['清爽耐看的外观','白色车身搭配简洁的轿车线条，给旅程一个清爽的开场。无论城市街景还是近郊风光，这份低调的视觉气质都很耐看。','A fresh, understated look','White bodywork and clean saloon lines give the journey a fresh opening. Its understated visual character sits naturally against city streets and nearby scenery.'],
        magotan:['简约有度的气质','规整的轿车轮廓与简洁线条，呈现沉稳、利落的视觉气质。日常出行或正式场合，都可以从这份恰到好处的设计感开始。','Composed, clean styling','A well-defined saloon silhouette and clean lines create a composed, polished look—a considered starting point for everyday journeys or formal occasions.'],
        passat:['经典黑色的从容感','黑色车身与经典轿车轮廓，带来成熟、克制的视觉印象。把这份简洁留给车，把更多精彩留给你沿途的安排。','A classic black silhouette','Black bodywork and a classic saloon shape create a mature, restrained impression. Let the car keep things simple while your itinerary supplies the colour.'],
        '718':['鲜明的跑车风格','敞篷跑车轮廓和流畅线条，让一次短途出发也有值得记住的仪式感。适合把车的外观风格也作为旅程的一部分来选择。','Distinctive sports-car styling','A roadster silhouette and flowing lines give even a short departure a sense of occasion. Choose it when the visual character of the car is part of your journey.'],
        x5:['醒目的 SUV 轮廓','清晰的 SUV 轮廓与富有层次的车身线条，呈现大方、鲜明的视觉风格。喜欢这种外观气质，可以把它列入你的出行候选。','A distinctive SUV silhouette','A well-defined SUV silhouette and layered body lines create a bold, generous visual presence. A candidate for those drawn to this style.'],
        my:['简洁现代的设计','简洁车身线条与现代感轮廓，和都市、湖畔的出行画面自然相衬。让外观选择也贴近你喜欢的生活方式。','Clean, contemporary design','Clean body lines and a contemporary silhouette sit naturally in city and lakeside settings. Let your choice of styling reflect the way you like to travel.'],
        e:['优雅克制的轿车气质','流畅的轿车轮廓与细致的外观线条，呈现优雅、克制的视觉印象。为正式出行或认真安排的一次旅程，添一份仪式感。','An elegant saloon profile','A flowing saloon profile and considered exterior lines create an elegant, restrained impression, adding a sense of occasion to a formal visit or a carefully planned trip.'],
        gl8:['温暖沉稳的商务风格','棕色车身搭配商务 MPV 轮廓，呈现温暖、沉稳的视觉气质。为一次会面或相聚，选一个与你期待的氛围相衬的开场。','Warm, composed MPV styling','Brown bodywork and an MPV silhouette create a warm, composed appearance—a visual opening that complements the atmosphere of a meeting or gathering.'],
        'gl8-653':['棕色车身的温暖气质','棕色外观与商务 MPV 轮廓相结合，带来温暖、沉稳的视觉印象。喜欢这份设计气质，可以继续了解具体版本与资料。','Warm brown styling','A brown exterior and an MPV silhouette create a warm, composed visual impression. Explore the exact version and references if this styling appeals to you.'],
        'denza-d9':['鲜明的现代 MPV 风格','现代 MPV 轮廓与有辨识度的车头设计，让相聚的出发也有自己的风格。喜欢这种视觉气质，可以继续了解具体车型资料。','A distinctive modern MPV','A modern MPV silhouette and a recognisable front design give your departure its own visual character. Explore the model information if this look appeals to you.'],
        coaster:['温暖的浅香槟棕外观','浅香槟棕车身与中巴轮廓，呈现温暖、统一的视觉气质。为团队行程选车时，也可以从你喜欢的外观氛围开始。','Warm champagne-brown styling','Light champagne-brown bodywork and a minibus silhouette create a warm, cohesive appearance. Exterior character can be part of choosing a vehicle for a group journey.'],
        h7:['黑色轿车的沉稳气质','黑色车身与舒展的轿车轮廓，带来沉稳、端正的视觉印象。为会面、接待或城市出行，添一份简洁而鲜明的风格。','A composed black saloon','Black bodywork and an elongated saloon profile create a composed, formal visual impression, bringing a clear, understated style to meetings, visits or city journeys.']
      };return stories[car.id]||['你喜欢的外观风格','从车型展示图出发，选择与你的旅程氛围相衬的外观，让每次出发都有自己的风格。','Styling for your journey','Use the vehicle image to choose a look that complements the atmosphere of your trip.'];
    }
    function matchReasons(car,n){
      const inside=car.price!=null&&car.price<=n.budget,spare=inside?n.budget-car.price:0,story=matchVehicleStory(car);
      const budgetText=inside?spare>0?matchCopy(`演示日租 ${money(car.price)}，比你的 ${money(n.budget)} 日预算上限低 ${money(spare)}。选车预算更有余量，也让整趟旅程的安排更从容。`,`The demo daily rate of ${money(car.price)} is ${money(spare)} below your ${money(n.budget)} daily limit, giving you more flexibility in choosing a car and planning the journey.`):matchCopy(`演示日租 ${money(car.price)}，在你的日预算范围内。让选车从清晰的价格开始，把心思留给接下来想去的地方。`,`The demo daily rate of ${money(car.price)} fits your daily limit. Begin with a clear vehicle price and turn your attention to the places you want to visit.`):matchCopy('先从你喜欢的车型风格开始，结合具体报价安排一趟期待已久的旅程。','Start with the vehicle style you like, then use the confirmed quote to plan a journey to look forward to.');
      return [{label:matchCopy('预算更从容','More flexibility in your budget'),text:budgetText},matchRouteReason(car,n),matchPreferenceReason(car,n)||{label:matchCopy(story[0],story[2]),text:matchCopy(story[1],story[3])}];
    }
    function matchResult(r,n){const first=r[0],en=state.lang==='en',name=c=>en?c.en:c.name;
      const checks=matchCopy(`${n.people} 人同行、${n.bags} 件行李：座位数、行李空间及你关注的“${n.priority}”需结合实车版本确认。`,`${n.people} travellers and ${n.bags} ${n.bags===1?'bag':'bags'}: confirm seating, luggage capacity and your “${t(n.priority)}” preference against the actual vehicle version.`);
      return `<section class="match-result" id="match-result" aria-labelledby="match-result-title"><div class="match-result-top"><span class="eyebrow">YOUR MATCH</span><span class="match-category">${matchCopy('行程候选','Journey candidates')}</span></div><div class="match-trip-summary">${n.start||n.destination?`<span data-i18n-preserve>${esc(n.start)} → ${esc(n.destination)}</span>`:''}<span>${t(n.type)}</span><span>${matchCopy('日预算','Daily budget')} ${money(n.budget)}</span><span>${matchCopy('偏好','Priority')} · ${t(n.priority)}</span></div>${state.matchPriorityRelaxed?`<p class="match-relaxed-note">${matchCopy(`预算内没有完全符合“${n.priority}”的候选，以下先按行程与同行人数筛选，偏好项未参与排序。`,`No within-budget candidate fully matches “${t(n.priority)}”. Results are filtered by journey and group size; the preference is not used in ranking.`)}</p>`:''}${matchRoutePlanHTML(n)}${n.bags>=3?`<p class="match-luggage-note">${matchCopy(`你选择了 ${n.bags} 件行李，本次只比较商务 MPV、中巴等装载候选；请结合箱子尺寸与同行人数确认具体装载方案。`,`For ${n.bags} bags, compare MPV and minibus loading candidates. Confirm the loading plan against luggage dimensions and the number of travellers.`)}</p>`:''}<article class="match-primary"><div class="match-vehicle-photo">${vehiclePhoto(first,'alt="'+esc(name(first))+'"')}${vehiclePhotoNotice(first)}</div><div class="match-primary-copy"><span class="eyebrow">${matchCopy('优先查看','First to consider')}</span><h2 id="match-result-title">${esc(name(first))}</h2><div class="match-price"><strong>${money(first.price)}</strong><span>${matchCopy('/ 天 · 演示日租价','/ day · demo daily rate')}</span></div><h3 class="match-reasons-title">${matchCopy('为什么推荐这辆车','Why consider this vehicle')}</h3><ol class="match-reasons">${matchReasons(first,n).map((reason,i)=>`<li><span class="match-reason-number">0${i+1}</span><div><b>${reason.label}</b><p>${reason.text}</p>${reason.sourceUrl?`<a class="match-reason-source" href="${reason.sourceUrl}" target="_blank" rel="noopener">${matchCopy('车型定位来源','Model positioning source')} ↗</a>`:''}</div></li>`).join('')}</ol><div class="match-confirmation"><b>${matchCopy('预订前确认','Confirm before booking')}</b><p>${checks}</p></div><a class="btn" href="#/car/${first.id}">${matchCopy('查看车辆与资料','View vehicle and references')} ↗</a></div></article>${r.length>1?`<div class="match-alternatives"><h3>${matchCopy('其他候选车型','Other vehicles to compare')}</h3><div class="match-alternative-grid">${r.slice(1).map(c=>`<a class="match-alternative" href="#/car/${c.id}"><div class="match-alternative-photo">${vehiclePhoto(c,'loading="lazy" alt="'+esc(name(c))+'"')}${vehiclePhotoNotice(c)}</div><div class="match-alternative-copy"><h4>${esc(name(c))}</h4><p>${matchCopy(`演示日租 ${money(c.price)} · ${c.scene===n.type?'同出行场景':'预算内备选'}`,`Demo ${money(c.price)} / day · ${c.scene===n.type?'Matching journey category':'Within-budget alternative'}`)}</p><span>${matchCopy('查看车辆','View vehicle')} ↗</span></div></a>`).join('')}</div></div>`:''}<details class="match-method"><summary>${matchCopy('了解推荐方式','How recommendations are selected')}</summary><p>${matchCopy('先验证已选择的起终点，结合目的地类别、同行人数和行李需求筛选车型类别，豪华感按高级/豪华车型定位、驾驶乐趣按跑车类别、空间按 MPV/SUV/中巴类别、环保按新能源分类筛选，再按出行场景与演示日租价排序；选择价格时按日租价优先。多人行程先比较 MPV/中巴，少人数山地行程先比较 SUV 类别；新能源方案另需确认续航与沿途补能。实车座位、空间、续航和山区适用性需核对，舒适配置等未核实信息不参与评分。','Selected places are validated first. Destination categories, group size and luggage needs guide body-type comparisons, Luxury uses executive/luxury model positioning, enjoyment uses sports-car categories, space uses MPV/SUV/minibus categories, and environmental preferences use the electric/hybrid category. Journey category and demo price then order candidates; price preference puts the daily rate first. Larger groups compare MPV/minibus categories; smaller groups visiting mountain destinations compare SUVs first. Electric options require range and charging confirmation. Confirm actual seats, space, range and mountain suitability; unverified equipment or comfort features are not scored.')}</p></details><p class="match-result-note">${matchCopy('推荐文案介绍外观风格与旅程灵感；图片为车型参考，具体实车版本、完整费用与驾驶资格在预订前确认。','The copy describes exterior styling and journey ideas. Images are model references; confirm the actual vehicle version, full costs and licence eligibility before booking.')}</p></section>`;
    }
    function match(){const r=state.match,n=matchRequest(),option=(value,label,selected)=>`<option value="${esc(value)}" ${String(value)===String(selected)?'selected':''}>${label}</option>`;return `<main class="page wrap"><div class="match-form"><span class="eyebrow">YICHEN MATCH</span><h1 style="font-size:clamp(2.7rem,5vw,4.5rem)">告诉我们你的旅程。</h1><p class="muted">${matchCopy('先选择真实的起点和目的地，再结合行程、预算与车型类别查看候选。','Select real starting and destination places, then compare candidates by journey, budget and body type.')}</p><form novalidate onsubmit="runMatch(event)" class="booking-content"><div class="form-grid">${matchPlacePickerHTML('start',n)}${matchPlacePickerHTML('destination',n)}<div class="formfield"><label for="m-people">出行人数</label><select id="m-people" onchange="matchTripChanged()">${[...Array(30).keys()].map(i=>i+1).map(x=>option(x,x+' 人',n.people)).join('')}</select></div><div class="formfield"><label for="m-bags">行李件数</label><select id="m-bags" onchange="matchTripChanged()">${[1,2,3,4,5,6,7,8].map(x=>option(x,x+' 件',n.bags)).join('')}</select></div><div class="formfield"><label for="m-type">旅行类型</label><select id="m-type" onchange="matchTripChanged()">${['周末出逃','家庭出游','户外探险','商务出行','团队出行','城市通勤'].map(x=>option(x,x,n.type)).join('')}</select></div><div class="formfield"><label for="m-budget">日预算</label><select id="m-budget" onchange="matchTripChanged()">${[700,1000,1500].map(x=>option(x,money(x)+' 以内',n.budget)).join('')}</select></div><div class="formfield" style="grid-column:1/-1"><label for="m-priority">最在意的维度</label><select id="m-priority" onchange="matchTripChanged()">${['舒适','空间','驾驶乐趣','豪华感','价格','环保'].map(x=>option(x,x,n.priority)).join('')}</select></div></div><button class="btn" style="margin-top:22px" type="submit">为我推荐 ↗</button></form>${r&&r.length?matchResult(r,n):r?matchEmptyResultHTML(n):''}</div></main>`}
    function inspiration(){return tourInspirationPage()}
    function about(){const cp=serviceCopy;return `<main class="page wrap about-company"><div class="subhero"><span class="eyebrow">ABOUT YC · ROOTED IN CHENGDU</span><h1>${cp('从成都出发，走进更好的旅程。','From Chengdu, towards a better journey.')}</h1><p>${cp('YC · 扎根成都的本土旅行租车公司','YC · A local travel and car rental company rooted in Chengdu')}</p></div><section class="section about-story"><span class="eyebrow">OUR STORY</span><h2>${cp('熟悉这座城，也关心你的下一站。','We know this city, and care about your next stop.')}</h2><p>${cp('YC 扎根本土成都，围绕旅行与用车，连接城市生活和四川山水。我们从你的目的地、同行人数、行李与预算出发，协助选择适合旅程的车型，让一次出发从清楚的安排开始。','Rooted in Chengdu, YC connects city life with the landscapes of Sichuan through travel and car rental. We help you compare vehicles around your destination, group, luggage and budget, beginning every journey with clear arrangements.')}</p><p>${cp('从机场到街巷，从周末短途到多人同行，我们希望用本地视角和细致沟通，让你自在感受成都，也从容探索更远的地方。','From airports to neighbourhoods, weekend escapes to group trips, our local perspective and thoughtful communication help you experience Chengdu and explore further.')}</p></section><section class="about-values"><article><span>01 / PURPOSE</span><h2>${cp('使命','Our purpose')}</h2><p>${cp('让旅行用车更简单，让每一次出发都有明确的选择和妥帖的安排。','Make travel and car rental simpler, with clear choices and thoughtful arrangements.')}</p></article><article><span>02 / VISION</span><h2>${cp('愿景','Our vision')}</h2><p>${cp('成为人们探索成都与四川时，愿意再次选择的本土出行伙伴。','Become the local travel partner people choose again when exploring Chengdu and Sichuan.')}</p></article><article><span>03 / VALUES</span><h2>${cp('企业文化','Our values')}</h2><p>${cp('真诚沟通、尊重需求、认真做事、热爱本土。把信息说清楚，把细节做扎实，把旅程交还给旅行者。','Communicate honestly, respect individual needs, work carefully and value our home. Clarify the details and leave travellers free to enjoy the journey.')}</p></article></section><section class="section about-story"><span class="eyebrow">OUR WAY</span><h2>${cp('把每个细节，放在出发之前。','Take care of the details before departure.')}</h2><p>${cp('了解行程后再建议车型；确认报价与取还车安排；结合实车核对座位、行李和配置。服务的起点，是认真听见你的需要。','Understand the journey before suggesting a vehicle; agree on the quote and pickup arrangements; check seats, luggage and equipment against the actual vehicle. Service begins with listening.')}</p><a class="btn" href="#/match">${cp('为旅程选车','Find a vehicle for your journey')} ↗</a></section></main>`}
    function admin(){return `<main class="page wrap"><div class="subhero"><span class="eyebrow">YC · OPERATIONS</span><h1>用车需求管理</h1><p>管理员登录后查看客户提交的需求、更新跟进状态和备注。</p><a class="btn" href="./operator.html">进入管理后台 ↗</a></div></main>`}
    let motionContext=null,motionRoute=null;
    function initMotion(route,isNewRoute){
      if(!window.gsap||window.matchMedia('(prefers-reduced-motion: reduce)').matches)return;
      document.documentElement.classList.add('has-gsap');
      if(window.ScrollTrigger)gsap.registerPlugin(ScrollTrigger);
      motionContext=gsap.context(()=>{
        if(isNewRoute){
          if(route==='/'){
            const tl=gsap.timeline({defaults:{duration:.56,ease:'power2.out'}});
            tl.from('.hero-copy .eyebrow',{y:10})
              .from('.hero-copy h1',{y:20},'-=.35')
              .from('.hero-copy p',{y:13},'-=.38')
              .from('.hero-actions',{y:11},'-=.38')
              .from('.search-wrap',{y:19,duration:.5},'-=.32');

            if(window.ScrollTrigger)gsap.to('.hero-image',{yPercent:4,ease:'none',scrollTrigger:{trigger:'.hero',start:'top top',end:'bottom top',scrub:true}});
          }else{
            const intro=app.querySelectorAll('.subhero .eyebrow,.subhero h1,.subhero p,.detail-top,.showroom,.booking-content,.route-info,.success .mark,.success h1');
            if(intro.length)gsap.from(intro,{y:15,duration:.58,ease:'power2.out',stagger:.06,clearProps:'transform,opacity,visibility'});
          }
        }
        if(window.ScrollTrigger){
          const reveal=app.querySelectorAll('.section-head,.journey-card,.fleet-card,.destination-card,.match-band,.benefit,.result-card');
          reveal.forEach(el=>gsap.from(el,{y:18,duration:.62,ease:'power2.out',clearProps:'transform,opacity,visibility',scrollTrigger:{trigger:el,start:'top 90%',once:true}}));
        }
      },app);
    }
    function render(){state.route=location.hash.slice(1)||'/';let route=state.route.split('?')[0];if(window.ensureRouteStyles&&!ensureRouteStyles(route,render))return;if(route==='/booking'){const query=new URLSearchParams(state.route.split('?')[1]||''),car=query.get('car')||state.booking?.car;state.route='/enquiry'+(car&&CARS.some(c=>c.id===car)?'?car='+encodeURIComponent(car):'');route='/enquiry';window.history.replaceState(null,'','#'+state.route);}if(route==='/enquiry'&&!window.libphonenumber){if(!app.querySelector('main.enquiry-page .subhero'))app.innerHTML=header()+'<main class="page wrap enquiry-page" data-intro-lang="'+state.lang+'">'+localizeHTML(enquiryIntroHTML())+'<p class="phone-loading" role="status">正在准备咨询表…</p></main>'+footer();loadEnquiryPhoneLibrary().then(()=>{if(location.hash.split('?')[0]==='#/enquiry')render()}).catch(()=>{if(location.hash.split('?')[0]!=='#/enquiry')return;app.querySelector('main').innerHTML='<h1>咨询表暂时无法加载</h1><p role="alert">请检查网络后重试；电话校验资料未就绪时不会提交需求。</p><button class="btn" onclick="render()">重新加载</button>'});return}if(route==='/experience'){state.route='/search';route='/search';window.history?.replaceState(null,'','#/search');}if(motionContext){motionContext.revert();motionContext=null}let isNewRoute=route!==motionRoute;motionRoute=route;let content=route==='/'?home():route==='/search'?search():route.startsWith('/car/')?(CARS.some(c=>c.id===route.split('/')[2])?carPage(route.split('/')[2]):notFoundPage()):route==='/booking'?bookingPage():route==='/success'?success():route==='/trips'?trips():route==='/garage'?garage():route==='/destinations'?destinations():route.startsWith('/route/')?tourRoutePage(route.split('/')[2]):route.startsWith('/destination/')?destination(route.split('/')[2]):route==='/match'?match():route==='/inspiration'?inspiration():route==='/enquiry'?enquiryPage():route==='/services'?servicePage():route==='/about'?about():route==='/admin'?admin():route==='/account'?accountPage():notFoundPage();disposeMaps();window.DestinationGallery?.dispose();commitPageHTML(localizeHTML(header()+content+footer()),route);const main=app.querySelector('main');if(main){main.id='main-content';main.tabIndex=-1}document.documentElement.lang=state.lang==='en'?'en':'zh-CN';document.title=(route==='/'?t('YICHEN Drive · 为旅程选择座驾'):app.querySelector('h1')?.textContent+' · YICHEN Drive');schedulePageMotion(route,isNewRoute);window.DestinationGallery?.mount(app);if(route==='/services')finishServicePage();if(route==='/enquiry')initEnquiryForm(document.querySelector('.enquiry-form'));if(route.startsWith('/car/'))loadVehicleReviews(route.split('/')[2]);if(state.map&&route==='/search')mountSearchMap();}
    function notFoundPage(){return `<main class="page wrap"><div class="subhero"><span class="eyebrow">404</span><h1>没有找到这个页面</h1><p>链接可能已失效，请返回车型列表继续选择。</p><a class="btn" href="#/search">查看车型</a></div></main>`}
    function esc(value){return String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
    function meetsCriterion(c,x){const spec=configFor(c);if(x==='5 座及以上')return meetsSeatCriterion(c,5);if(x==='7 座及以上')return meetsSeatCriterion(c,7);if(x==='3 件行李及以上'){const bags=carBags(c);return bags!=null?bags>=3:/MPV|中巴/.test(c.type)}if(x==='AWD / 四驱')return spec.verified?spec.drive==='AWD':['x5','my','denza-d9'].includes(c.id);if(x==='自动挡')return spec.verified?spec.transmission==='自动挡':['718','x5','my','e','gl8','gl8-653','h7','magotan','passat','denza-d9'].includes(c.id);return x==='Apple CarPlay'?spec.verified&&spec.carplay===true:false}
    function locationOptions(query=''){return regionalLocationOptions(query)}
    function showLocations(){let panel=q('location-panel'),input=q('pickup');if(!panel||!input)return;panel.hidden=false;input.setAttribute('aria-expanded','true');panel.innerHTML=localizeHTML(locationOptions(input.value===(placeById(book().pickupId)?placeLabel(placeById(book().pickupId)):book().pickup)?'':input.value))}
    function hideLocations(){let panel=q('location-panel'),input=q('pickup');if(panel)panel.hidden=true;if(input)input.setAttribute('aria-expanded','false')}
    function locationTyped(value){regionalLocationTyped(value)}
    function locationKeydown(e){if(e.key==='Escape'){hideLocations();return}if(e.key==='Enter'){e.preventDefault();let option=q('location-panel')?.querySelector('.location-option');if(option)option.click();else showLocations()}if(e.key==='ArrowDown'){e.preventDefault();showLocations();q('location-panel')?.querySelector('.location-option')?.focus()}}
    function chooseLocation(id){regionalChooseLocation(id)}
    function kmBetween(a,b,c,d){const rad=x=>x*Math.PI/180,R=6371,dl=rad(c-a),dn=rad(d-b),h=Math.sin(dl/2)**2+Math.cos(rad(a))*Math.cos(rad(c))*Math.sin(dn/2)**2;return 2*R*Math.asin(Math.sqrt(h))}
    function useCurrentLocation(){regionalCurrentLocation()}
    function editTrip(){nav('/');q('pickup')?.focus()}
    function doSearch(e){e.preventDefault();let place=placeById(state.selectedLocationId),start=q('start').value,end=q('end').value;if(!place){showLocations();q('pickup').focus();toast('请从列表中选择具体取车地点');return}if(start<dateAfter(0)){toast('取车日期不能早于今天');return}if(!start||!end||!Number.isFinite(Date.parse(start))||!Number.isFinite(Date.parse(end))||new Date(end)<new Date(start)){toast('还车日期不能早于取车日期');return}if((Date.parse(end)-Date.parse(start))/86400000>30){toast('估算租期不能超过30天');return}state.booking={...book(),pickup:place.name,pickupId:place.id,pickupDetail:place.detail,pickupPosition:{lat:place.lat,lon:place.lon},start,end,timeConfirmed:false,same:q('same').checked};save();state.filter='全部';state.sort='推荐';nav('/search')}
    function chip(x){if(['价格最低','价格最高','推荐'].includes(x)){state.sort=x;}else state.filter=x;syncSearchFilters();render()}
    function restoreSearchOptions(params){state.sort=['推荐','价格最低','价格最高'].includes(params.get('sort'))?params.get('sort'):'推荐';state.maxPrice=params.has('maxPrice')?Math.max(200,Math.min(1500,Number(params.get('maxPrice'))||1500)):1500;const allowed=['5 座及以上','7 座及以上','3 件行李及以上','AWD / 四驱','自动挡','Apple CarPlay'];state.criteria=params.getAll('criterion').filter(x=>allowed.includes(x));}
    function syncSearchFilters(){const params=new URLSearchParams({filter:state.filter,brand:state.brand||'all',sort:state.sort,maxPrice:String(state.maxPrice)});state.criteria.forEach(x=>params.append('criterion',x));state.route='/search?'+params;if(window.history?.replaceState)window.history.replaceState(null,'','#'+state.route);else location.hash='#'+state.route;}
    function setFilter(x){state.filter=x;syncSearchFilters();render()}
    function setBrand(id){state.brand=BRANDS.some(b=>b.id===id)?id:'all';syncSearchFilters();render()}
    function clearSearchFilters(){state.filter='全部';state.brand='all';state.criteria=[];state.maxPrice=1500;state.sort='推荐';syncSearchFilters();render()}
    function criteriaChange(x,yes){state.criteria=yes?[...state.criteria,x]:state.criteria.filter(y=>y!==x);syncSearchFilters();render()}
    function toggleFilter(){state.mobileFilter=!state.mobileFilter;render()}
    function favorite(id){state.favorites=state.favorites.includes(id)?state.favorites.filter(x=>x!==id):[...state.favorites,id].slice(-3);save();render();toast(state.favorites.includes(id)?'已加入我的车库':'已从车库移除')}
    function toggleLang(){const drafts=Array.from(app.querySelectorAll?.('input[id],select[id]')||[]).map(el=>({id:el.id,value:el.value,checked:el.checked}));state.lang=state.lang==='zh'?'en':'zh';state.authError='';localStorage.setItem('yichen-lang',state.lang);render();for(const draft of drafts){const el=q(draft.id);if(!el)continue;if(['m-start','m-dest'].includes(draft.id)&&matchPlaceById(el.dataset.placeId)){el.value=matchPlaceName(matchPlaceById(el.dataset.placeId));continue}if(draft.id==='pickup'&&placeById(state.selectedLocationId)){el.value=placeLabel(placeById(state.selectedLocationId));continue}el.value=draft.value;if(el.type==='checkbox')el.checked=draft.checked}toast(state.lang==='en'?'Language changed to English':'已切换为中文')}
    function toggleMenu(){const open=q('mobile-panel').classList.toggle('open');document.querySelector('.mobile-menu')?.setAttribute('aria-expanded',String(open))}
    function showAccount(){nav('/account')}
    function startBooking(id){if(!CARS.some(c=>c.id===id))return;state.booking={...book(),car:id};save();nav('/enquiry?car='+encodeURIComponent(id))}
    function extra(x,yes){state.extras=yes?[...state.extras,x]:state.extras.filter(y=>y!==x);render()}
    function bookingBack(){if(state.step===1)nav('/car/'+book().car);else{state.step--;render()}}
    function bookingNext(){nav('/enquiry'+(state.booking?.car?'?car='+encodeURIComponent(state.booking.car):''))}
    function runMatch(e){submitRouteMatch(e)}
    function calendar(){let b=book(),c=CARS.find(x=>x.id===b.car);let start=b.start.replace(/[-:]/g,'').replace('T','T')+'00',end=b.end.replace(/[-:]/g,'').replace('T','T')+'00';let url=`https://calendar.google.com/calendar/render?action=TEMPLATE&text=${encodeURIComponent('YICHEN Drive · '+c.name)}&dates=${start}/${end}&details=${encodeURIComponent('演示行程 '+b.order)}&location=${encodeURIComponent(b.pickup)}`;window.open(url,'_blank','noopener')}
    async function shareTrip(){let text=`YICHEN Drive 演示行程：${esc(book().pickup)} · ${book().start.slice(0,10)}`;if(navigator.share){try{await navigator.share({title:'我的旅程',text})}catch{}}else{try{await navigator.clipboard.writeText(text);toast('行程摘要已复制')}catch{toast(text)}}}
    if(!PLACES.some(p=>p.id===book().pickupId)&&!book().pickupId?.startsWith('amap-')){state.booking=null;sessionStorage.removeItem('yichen-booking')}
    window.addEventListener('hashchange',()=>{state.route=location.hash.slice(1)||'/';render();window.scrollTo(0,0)});document.addEventListener('click',e=>{if(!e.target.closest('.location-field'))hideLocations()});if(book().pickupId?.startsWith('amap-')&&book().pickupPosition){state.remotePlaces=[{id:book().pickupId,name:book().pickup,detail:book().pickupDetail,...book().pickupPosition}]}state.selectedLocationId=book().pickupId||PLACES.find(p=>p.name===book().pickup)?.id||null;render();
    bootstrapServices();

// Keep the parser-painted hero in place while attaching the rest of the live page.
function commitPageHTML(html,route){
 const main=app.querySelector('main'),home=route==='/',anchor=main?.querySelector(home?':scope > .hero':':scope > .subhero'),language=home?'heroLang':'introLang';
 if((home||(route==='/enquiry'&&main?.classList.contains('enquiry-page')))&&anchor&&(main.dataset[language]||'zh')===state.lang){
  const template=document.createElement('template');template.innerHTML=html;
  const nextMain=template.content.querySelector('main');nextMain.querySelector(home?'.hero':'.subhero').remove();
  for(const child of [...main.children])if(child!==anchor)child.remove();
  main.append(...nextMain.childNodes);main.dataset[language]=state.lang;
  for(const child of [...app.children])if(child!==main)child.remove();
  app.prepend(template.content.querySelector('header'));app.append(template.content.querySelector('footer'));
 }else{app.innerHTML=html;const home=app.querySelector('main:has(> .hero)');if(home)home.dataset.heroLang=state.lang}
 app.removeAttribute('data-first-paint');if(window.yichenPendingPickup&&q('pickup')){window.yichenPendingPickup=false;q('pickup').focus()}
}
